/**
 * The theme options for MUI's createTheme: both colour schemes, in MUI's CSS-variables mode, switched
 * by `data-theme` as the SOLAR tokens are, so `data-theme="dark"` on any element turns a stock
 * MUI component and a SOLAR one to Dark together. The palette stays literal per scheme: MUI
 * derives channels and shades from it, which a var() cannot give.
 */
export function createSolarThemeOptions() {
  return {
    cssVariables: { colorSchemeSelector: '[data-theme="%s"]' },
    colorSchemes: {
      light: { palette: solarMuiPalette.light },
      dark: { palette: solarMuiPalette.dark },
    },
    breakpoints: { values: solarMuiBreakpoints },
    spacing: solarMuiSpacing,
    transitions: solarMuiTransitions,
    shape: { borderRadius: parseFloat(solarTokens.light['radius.control']) },
    zIndex: solarZIndex,
    typography: { ...solarResponsiveTypography, ...solarMuiTypography },
    // Stock MUI components drawn from SOLAR recipes (spec/overlay/mui-theme.yaml).
    components: solarMuiComponents,
  };
}
